components.css:
.ds-primary { display: inline-flex; align-items: center; justify-content: center; gap: .6rem; min-height: 3rem; box-sizing: border-box; padding: .6rem 1rem; border-radius: 8px; background: #ffda59; color: #101c36; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: .94rem; font-weight: 750; text-decoration: none; transition: background-color 160ms ease, border-color 160ms ease; }
.ds-primary:hover { background: #ffe78e; }
.ds-primary:focus-visible { outline: 3px solid #ffda59; outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-primary { transition: none; } }

.ds-secondary-surface { display: inline-flex; align-items: center; padding: .3rem .8rem; background: #101c36; }
.ds-secondary { display: inline-flex; align-items: center; min-height: 3rem; color: #fff; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: .94rem; font-weight: 750; text-decoration: underline; text-underline-offset: .2em; }
.ds-secondary:hover { text-decoration-thickness: 2px; }
.ds-secondary:focus-visible { outline: 3px solid #ffda59; outline-offset: 4px; }

.ds-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .625rem; }
.ds-option { display: flex; align-items: center; gap: .65rem; background: #fff; border: 1px solid #7389aa; border-radius: 8px; min-height: 3rem; padding: .45rem .65rem; color: #14233d; font: 700 1rem/1.6 Inter, ui-sans-serif, system-ui, sans-serif; cursor: pointer; transition: background-color 160ms ease, border-color 160ms ease; }
.ds-option-letter { display: grid; place-items: center; width: 1.55rem; height: 1.55rem; color: #394f74; border-radius: 4px; background: #edf3ff; font-size: .77rem; }
.ds-option:hover { background: #edf3ff; border-color: #4671c5; }
.ds-option[data-result="correct"] { background: #e0f4e9; border-color: #398057; }
.ds-option[data-result="incorrect"] { background: #fbeae8; border-color: #b95849; }
.ds-option:focus-visible { outline: 3px solid #4671c5; outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-option { transition: none; } }

.ds-question { background: #fff; color: #14233d; border-radius: 14px; box-shadow: 0 24px 52px rgb(0 0 0 / 19%); overflow: hidden; font-family: Inter, ui-sans-serif, system-ui, sans-serif; line-height: 1.6; }
.ds-question-band { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; column-gap: .8rem; padding-inline: clamp(1rem, 2.2vw, 1.75rem); background: #edf3ff; color: #394f74; font-size: .83rem; }
.ds-question-top { min-height: 3rem; font-weight: 750; }
.ds-question-body { padding: clamp(1rem, 2.2vw, 1.75rem); }
.ds-question-source { margin: 0 0 .75rem; font-size: .82rem; color: #52617a; font-weight: 650; }
.ds-question-body h2 { margin: 0 0 1.15rem; font-family: Manrope, system-ui, sans-serif; font-size: clamp(1.12rem, 1.65vw, 1.45rem); font-weight: 650; line-height: 1.4; letter-spacing: -.011em; text-wrap: pretty; }
.ds-answer { display: grid; gap: .25rem; margin-top: 1rem; border-top: 1px solid #d4deed; padding-top: .85rem; font-size: .9rem; line-height: 1.45; }
.ds-answer p { margin: 0; color: #52617a; }
.ds-question-foot { min-height: 3.2rem; padding-block: .2rem; }
.ds-question-foot a { color: inherit; display: inline-flex; align-items: center; gap: .4rem; min-height: 44px; font-weight: 700; text-underline-offset: .2em; }
.ds-question-foot a:hover { text-decoration-thickness: 2px; }
.ds-question-foot a:focus-visible { outline: 3px solid #4671c5; outline-offset: 4px; }
.ds-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .625rem; }
.ds-option { display: flex; align-items: center; gap: .65rem; background: #fff; border: 1px solid #7389aa; border-radius: 8px; min-height: 3rem; padding: .45rem .65rem; color: #14233d; font: 700 1rem/1.6 Inter, ui-sans-serif, system-ui, sans-serif; cursor: pointer; transition: background-color 160ms ease, border-color 160ms ease; }
.ds-option-letter { display: grid; place-items: center; width: 1.55rem; height: 1.55rem; color: #394f74; border-radius: 4px; background: #edf3ff; font-size: .77rem; }
.ds-option:hover { background: #edf3ff; border-color: #4671c5; }
.ds-option[data-result="correct"] { background: #e0f4e9; border-color: #398057; }
.ds-option[data-result="incorrect"] { background: #fbeae8; border-color: #b95849; }
.ds-option:focus-visible { outline: 3px solid #4671c5; outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-option { transition: none; } }

.ds-report { border-radius: 14px; background: #1b2d50; color: #fff; padding: clamp(1rem, 3vw, 2rem); font-family: Inter, ui-sans-serif, system-ui, sans-serif; line-height: 1.6; }
.ds-report-top { display: flex; align-items: center; justify-content: space-between; gap: .25rem 1rem; flex-wrap: wrap; }
.ds-report-top small, .ds-score span { color: #c9d9f4; }
.ds-score { display: grid; gap: .4rem; margin-block: 1.8rem; }
.ds-score strong { color: #ffda59; font: 800 clamp(2.5rem, 6vw, 5rem)/1 Manrope, system-ui, sans-serif; font-variant-numeric: tabular-nums; letter-spacing: -.035em; }
.ds-score small { font-size: .42em; color: #c9d9f4; }
.ds-report-row { display: flex; justify-content: space-between; align-items: center; gap: .7rem; min-height: 3rem; border-top: 1px solid #627595; font-size: .9rem; color: inherit; }
.ds-report-row strong { text-align: right; }
a.ds-report-row { text-underline-offset: .2em; }
a.ds-report-row:hover { text-decoration-thickness: 2px; }
a.ds-report-row:focus-visible { outline: 3px solid #ffda59; outline-offset: 4px; }

.ds-evidence { display: grid; grid-template-columns: 1fr 1fr auto; align-items: center; gap: 1.25rem; padding: 1rem 1.5rem; background: #ffda59; color: #14233d; font-family: Inter, ui-sans-serif, system-ui, sans-serif; }
.ds-evidence p { display: flex; align-items: center; gap: .75rem; margin: 0; line-height: 1.22; }
.ds-evidence strong { font: 800 clamp(1.55rem, 3vw, 2.5rem)/1 Manrope, system-ui, sans-serif; font-variant-numeric: tabular-nums; }
.ds-evidence span { font-size: .89rem; font-weight: 650; }
.ds-evidence a { display: inline-flex; align-items: center; gap: .4rem; min-height: 44px; font-weight: 700; color: inherit; text-underline-offset: .2em; }
.ds-evidence a:hover { text-decoration-thickness: 2px; }
.ds-evidence a:focus-visible { outline: 3px solid #4671c5; outline-offset: 4px; }
@media (max-width: 820px) { .ds-evidence { grid-template-columns: 1fr 1fr; gap: .5rem 1rem; } .ds-evidence a { grid-column: 1 / -1; width: fit-content; } }
@media (max-width: 570px) { .ds-evidence { padding-inline: 1rem; } .ds-evidence p { align-items: start; flex-direction: column; gap: .35rem; } }

.ds-header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; min-height: 4.75rem; padding-inline: 1.5rem; border-bottom: 1px solid #344666; background: #101c36; color: #fff; font-family: Inter, ui-sans-serif, system-ui, sans-serif; }
.ds-header a { text-decoration: none; }
.ds-brand { display: inline-flex; align-items: center; gap: .45rem; color: inherit; font: 800 1.15rem/1.1 Manrope, system-ui, sans-serif; white-space: nowrap; }
.ds-brand svg { flex: none; }
.ds-nav { display: flex; align-items: center; gap: clamp(.9rem, 3vw, 2.5rem); }
.ds-nav a, .ds-signin { display: inline-flex; align-items: center; min-height: 44px; font-size: .9rem; font-weight: 650; }
.ds-nav a { color: #c9d9f4; }
.ds-signin { color: inherit; white-space: nowrap; border: 1px solid #667899; padding-inline: .9rem; border-radius: 8px; }
.ds-nav a:hover, .ds-signin:hover { text-decoration: underline; text-underline-offset: .2em; }
.ds-header a:focus-visible { outline: 3px solid #ffda59; outline-offset: 4px; }
@media (max-width: 570px) { .ds-header { display: grid; grid-template-columns: 1fr auto; gap: 0 .5rem; padding: .45rem 1rem 0; } .ds-nav { grid-column: 1 / -1; grid-row: 2; gap: 1rem; } .ds-signin { grid-column: 2; grid-row: 1; } .ds-nav a, .ds-signin { font-size: .82rem; } }
